/**
 * Where to connect (docs/spikes/05-connection-params.md). Priority:
 * 1. Native launch parameters (iOS process args / Android intent extras), via @quiesco/native.
 * 2. Web: `window.__QUIESCO__` injected by Playwright's addInitScript.
 * 3. Build-time fallback generated by withQuiesco (`EXPO_PUBLIC_QUIESCO_PORT`).
 * 4. DEFAULT_PORT with no session (JS-only mode, single device).
 */
import { DEFAULT_PORT, WEB_PARAMS_GLOBAL } from '@quiesco/protocol';

export interface ConnectionParams {
  port: number;
  session: string | null;
  source: 'native' | 'web-global' | 'build' | 'default';
}

export interface ParamSources {
  native: { port?: string; session?: string } | null;
  global: Record<string, unknown>;
  build: { port: number | null; session: string | null };
}

function toPort(v: unknown): number | null {
  const n = typeof v === 'number' ? v : typeof v === 'string' ? Number.parseInt(v, 10) : Number.NaN;
  return Number.isInteger(n) && n > 0 && n < 65536 ? n : null;
}

export function resolveParams(src: ParamSources): ConnectionParams {
  const nativePort = toPort(src.native?.port);
  if (nativePort !== null) return { port: nativePort, session: src.native?.session ?? null, source: 'native' };

  const web = src.global[WEB_PARAMS_GLOBAL] as { port?: unknown; session?: unknown } | undefined;
  const webPort = toPort(web?.port);
  if (webPort !== null) return { port: webPort, session: typeof web?.session === 'string' ? web.session : null, source: 'web-global' };

  const buildPort = toPort(src.build.port);
  if (buildPort !== null) return { port: buildPort, session: src.build.session, source: 'build' };

  return { port: DEFAULT_PORT, session: null, source: 'default' };
}
